🐛 Describe the bug
This currently already happens to non-mutable ops.
def test_nonmutable_op_register_replacement(self):
    from torch._inductor.pattern_matcher import fwd_only

    @torch.library.custom_op("mylib::foo", mutates_args={})
    def foo(x: torch.Tensor) -> torch.Tensor:
        return x + 1

    @torch.library.register_fake("mylib::foo")
    def foo_fake(x: torch.Tensor) -> torch.Tensor:
        return x + 1

    @torch.library.custom_op("mylib::bar", mutates_args={})
    def bar(x: torch.Tensor) -> torch.Tensor:
        return x + 2

    @torch.library.register_fake("mylib::bar")
    def bar_fake(x: torch.Tensor) -> torch.Tensor:
        return x + 2

    @torch.library.custom_op("mylib::baz", mutates_args={})
    def baz(x: torch.Tensor) -> torch.Tensor:
        return x + 3

    @torch.library.register_fake("mylib::baz")
    def baz_fake(x: torch.Tensor) -> torch.Tensor:
        return x + 3

    @torch.library.custom_op("mylib::foobarbaz", mutates_args={})
    def foobarbaz(x: torch.Tensor) -> torch.Tensor:
        return x + 77

    @torch.library.register_fake("mylib::foobarbaz")
    def foobarbaz_fake(x: torch.Tensor) -> torch.Tensor:
        return x + 77

    def pattern(a):
        b = foo(a)
        c = bar(b)
        return c

    def replacement(a):
        return foobarbaz(a)

    inp = torch.randn(3)

    my_patterns = PatternMatcherPass()
    register_replacement(
        search_fn=pattern,
        replace_fn=replacement,
        example_inputs=[inp.clone().detach()],
        trace_fn=fwd_only,
        pass_dicts=my_patterns,
    )

    count = 0

    def custom_pass(graph: torch.fx.Graph):
        nonlocal count
        count = my_patterns.apply(graph)

    def custom_backend(graph: torch.fx.GraphModule, example_inputs):
        from torch._inductor import config

        current_config = config.shallow_copy_dict()
        from torch._inductor.compile_fx import compile_fx

        current_config["post_grad_custom_post_pass"] = custom_pass
        return compile_fx(graph, example_inputs, config_patches=current_config)

    @torch.compile(fullgraph=True, backend=custom_backend)
    def f1(a):
        b = foo(a)
        c = bar(b)
        d = baz(b)
        return c + d

    f1_inp = inp.clone().detach()
    f1_out = f1(f1_inp)
    self.assertEqual(count, 1)
The pattern translates to this FX IR:
graph():
    %arg0_1 : [num_users=1] = placeholder[target=arg0_1]
    %foo : [num_users=1] = call_function[target=torch.ops.mylib.foo.default](args = (%arg0_1,), kwargs = {})
    %bar : [num_users=1] = call_function[target=torch.ops.mylib.bar.default](args = (%foo,), kwargs = {})
    return bar
which fails to produce a match in the user program's FX IR:
graph():
    %arg0_1 : [num_users=1] = placeholder[target=arg0_1]
    %foo : [num_users=2] = call_function[target=torch.ops.mylib.foo.default](args = (%arg0_1,), kwargs = {})
    %bar : [num_users=1] = call_function[target=torch.ops.mylib.bar.default](args = (%foo,), kwargs = {})
    %baz : [num_users=1] = call_function[target=torch.ops.mylib.baz.default](args = (%foo,), kwargs = {})
    %add : [num_users=1] = call_function[target=torch.ops.aten.add.Tensor](args = (%bar, %baz), kwargs = {})
    return (add,)
due to difference in foo's number of users.
